package net.officefloor.hq.app.setting;

import java.util.Arrays;
import java.util.Optional;

/** The role a sheet's settings give a user name; any name not given one is a clerk. A viewer sees
 *  everything and can change nothing. A restricted user acts as a clerk, but sees on the people list
 *  only the people of the crews they lead or belong to and themselves. */
public enum Role {
    CLERK, STEWARD, VIEWER, RESTRICTED;

    /** The name the screen and the audit use for the role. */
    public String label() {
        return name().toLowerCase();
    }

    /** The role with this label; empty when there is none. */
    public static Optional<Role> of(String label) {
        return Arrays.stream(values()).filter(role -> role.label().equals(label)).findFirst();
    }
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** Make a change to the sheet, then record in the audit the figures it moved. The sheet is held
     *  locked throughout, so a change made at the same moment waits and the figures are its own. */
    @Transactional
    public <T> T track(String sheetId, String user, Supplier<T> change) {
        sheets.lock(sheetId);
        Rollup before = rollup(sheetId);
        T result = change.get();
        Rollup after = rollup(sheetId);
        after.people().forEach((id, figures) -> {
            if (!figures.sameAs(before.people().get(id))) {
                audit.recordOnCommit(rollupLine(sheetId, user, figures));
            }
        });
        if (after.claimedTotal().compareTo(before.claimedTotal()) != 0
                || after.dueTotal().compareTo(before.dueTotal()) != 0
                || after.overdueTotal().compareTo(before.overdueTotal()) != 0) {
            audit.recordOnCommit(totalsLine(sheetId, user, after));
        }
        BigDecimal threshold = settings.alertThreshold(sheetId);
        if (threshold != null) {
            after.people().forEach((id, figures) -> {
                Figures was = before.people().get(id);
                if (above(figures.due(), threshold) && (was == null || !above(was.due(), threshold))) {
                    audit.recordOnCommit("ALERT sheet=" + sheetId + " by=" + user + " name=" + figures.name()
                            + " due-total=" + figures.due().toPlainString());
                }
-- The sheet's today when the period was last locked, so a period read as of an earlier day shows it
-- not locked then; null while it is not locked, or for one locked before this was kept.
ALTER TABLE period ADD COLUMN locked_on DATE;

